"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[79800],{29081(e,a,o){o.r(a),o.d(a,{assets:()=>i,contentTitle:()=>c,default:()=>l,frontMatter:()=>t,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"cursos/react/modulos/arquitectura-final/cuestionario","title":"Cuestionario M24 \u2014 Arquitectura Final y Mejores Pr\xe1cticas","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/react/modulos/24-arquitectura-final/cuestionario.md","sourceDirName":"cursos/react/modulos/24-arquitectura-final","slug":"/cursos/react/modulos/arquitectura-final/cuestionario","permalink":"/sasf-temarios/cursos/react/modulos/arquitectura-final/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/react/modulos/arquitectura-final/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/react/modulos/arquitectura-final/ejercicio"}}');var s=o(74848),r=o(28453);const t={sidebar_label:"Cuestionario"},c="Cuestionario M24 \u2014 Arquitectura Final y Mejores Pr\xe1cticas",i={},d=[{value:"1. [Investigar] \xbfQu\xe9 son los Micro-Frontends con Module Federation (Webpack 5) y c\xf3mo se comparan con una arquitectura feature-based monorepo? \xbfCu\xe1ndo justifica la complejidad de micro-frontends?",id:"1-investigar-qu\xe9-son-los-micro-frontends-con-module-federation-webpack-5-y-c\xf3mo-se-comparan-con-una-arquitectura-feature-based-monorepo-cu\xe1ndo-justifica-la-complejidad-de-micro-frontends",level:3},{value:"2. [Investigar] \xbfQu\xe9 es Nx monorepo y c\xf3mo mejora la arquitectura de un proyecto React? Nx (de Nrwl) ofrece generators, dependency graph, affected commands, y computation caching.",id:"2-investigar-qu\xe9-es-nx-monorepo-y-c\xf3mo-mejora-la-arquitectura-de-un-proyecto-react-nx-de-nrwl-ofrece-generators-dependency-graph-affected-commands-y-computation-caching",level:3},{value:"3. [Investigar] \xbfQu\xe9 es &quot;Bulletproof React&quot; (de Alan Alickovic) y c\xf3mo estructura un proyecto React &quot;production-ready&quot;? Compar\xe1 su enfoque con la arquitectura de la clase.",id:"3-investigar-qu\xe9-es-bulletproof-react-de-alan-alickovic-y-c\xf3mo-estructura-un-proyecto-react-production-ready-compar\xe1-su-enfoque-con-la-arquitectura-de-la-clase",level:3},{value:"4. [Investigar] \xbfQu\xe9 es &quot;Tao of React&quot; (de Alexander Kondov) y qu\xe9 principios de arquitectura propone que difieren de la clase?",id:"4-investigar-qu\xe9-es-tao-of-react-de-alexander-kondov-y-qu\xe9-principios-de-arquitectura-propone-que-difieren-de-la-clase",level:3},{value:"5. [Conectar] La clase presenta Clean Architecture y Atomic Design. Conect\xe1 estos conceptos con el libro &quot;Clean Architecture&quot; de Robert C. Martin. \xbfC\xf3mo se traducen &quot;dependency rule&quot;, &quot;entities&quot;, y &quot;use cases&quot; al frontend React?",id:"5-conectar-la-clase-presenta-clean-architecture-y-atomic-design-conect\xe1-estos-conceptos-con-el-libro-clean-architecture-de-robert-c-martin-c\xf3mo-se-traducen-dependency-rule-entities-y-use-cases-al-frontend-react",level:3},{value:"6. [Conectar] La clase organiza features con carpetas autocontenidas. Conect\xe1 esto con &quot;cohesi\xf3n funcional&quot; vs &quot;cohesi\xf3n t\xe9cnica&quot;. \xbfPor qu\xe9 agrupar por feature es superior a agrupar por tipo en proyectos grandes?",id:"6-conectar-la-clase-organiza-features-con-carpetas-autocontenidas-conect\xe1-esto-con-cohesi\xf3n-funcional-vs-cohesi\xf3n-t\xe9cnica-por-qu\xe9-agrupar-por-feature-es-superior-a-agrupar-por-tipo-en-proyectos-grandes",level:3},{value:"7. [Conectar] La clase usa ESLint strict rules. Conect\xe1 esto con el concepto de &quot;static analysis beyond ESLint&quot;. \xbfQu\xe9 herramientas complementan ESLint para mantener la calidad de c\xf3digo en un proyecto React?",id:"7-conectar-la-clase-usa-eslint-strict-rules-conect\xe1-esto-con-el-concepto-de-static-analysis-beyond-eslint-qu\xe9-herramientas-complementan-eslint-para-mantener-la-calidad-de-c\xf3digo-en-un-proyecto-react",level:3},{value:"8. [Cuestionar] \xbfFeature-based vs Domain-Driven Design (DDD) en frontend? La clase usa feature-based. \xbfDeber\xedamos aplicar conceptos de DDD (aggregates, bounded contexts) a la arquitectura React?",id:"8-cuestionar-feature-based-vs-domain-driven-design-ddd-en-frontend-la-clase-usa-feature-based-deber\xedamos-aplicar-conceptos-de-ddd-aggregates-bounded-contexts-a-la-arquitectura-react",level:3},{value:"9. [Cuestionar] \xbfMonorepo vs polyrepo para proyectos React? La clase usa un solo repo. \xbfCu\xe1ndo un polyrepo (m\xfaltiples repos) es mejor?",id:"9-cuestionar-monorepo-vs-polyrepo-para-proyectos-react-la-clase-usa-un-solo-repo-cu\xe1ndo-un-polyrepo-m\xfaltiples-repos-es-mejor",level:3},{value:"10. [Cuestionar] \xbfAtomic Design es sobre-ingenier\xeda para la mayor\xeda de proyectos React? Brad Frost cre\xf3 Atomic Design para design systems. \xbfCu\xe1ndo justifica su uso y cu\xe1ndo es una estructura innecesaria?",id:"10-cuestionar-atomic-design-es-sobre-ingenier\xeda-para-la-mayor\xeda-de-proyectos-react-brad-frost-cre\xf3-atomic-design-para-design-systems-cu\xe1ndo-justifica-su-uso-y-cu\xe1ndo-es-una-estructura-innecesaria",level:3}];function u(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"cuestionario-m24--arquitectura-final-y-mejores-pr\xe1cticas",children:"Cuestionario M24 \u2014 Arquitectura Final y Mejores Pr\xe1cticas"})}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,s.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"1-investigar-qu\xe9-son-los-micro-frontends-con-module-federation-webpack-5-y-c\xf3mo-se-comparan-con-una-arquitectura-feature-based-monorepo-cu\xe1ndo-justifica-la-complejidad-de-micro-frontends",children:"1. [Investigar] \xbfQu\xe9 son los Micro-Frontends con Module Federation (Webpack 5) y c\xf3mo se comparan con una arquitectura feature-based monorepo? \xbfCu\xe1ndo justifica la complejidad de micro-frontends?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Micro-Frontends dividen una app React en m\xfaltiples sub-aplicaciones independientes, cada una con su propio build, deploy, y equipo. Module Federation (Webpack 5, tambi\xe9n soportado por Vite via ",(0,s.jsx)(a.code,{children:"@originjs/vite-plugin-federation"}),") permite que estas sub-apps compartan dependencias en runtime. Comparado con una arquitectura feature-based monorepo (donde todo vive en un solo repo y build): micro-frontends permiten deploys independientes, diferentes versiones de React, y equipos aut\xf3nomos. La complejidad extra (orquestaci\xf3n, estilos compartidos, comunicaci\xf3n cross-app) solo se justifica para aplicaciones muy grandes con m\xfaltiples equipos (50+ desarrolladores)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Luca Mezzalira (autor de "Building Micro-Frontends") recomienda micro-frontends solo cuando la organizaci\xf3n tiene equipos independientes que necesitan deploys independientes. Para TaskFlow o incluso una app mediana, micro-frontends son sobre-ingenier\xeda severa. La arquitectura feature-based (que combina features en un solo build) es suficiente hasta que tengas problemas de coordinaci\xf3n entre equipos. Fuente: "Micro-Frontends" por Luca Mezzalira, Module Federation docs, y "Micro-Frontends: The Good, the Bad, and the Ugly" en el blog de ThoughtWorks.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-nx-monorepo-y-c\xf3mo-mejora-la-arquitectura-de-un-proyecto-react-nx-de-nrwl-ofrece-generators-dependency-graph-affected-commands-y-computation-caching",children:"2. [Investigar] \xbfQu\xe9 es Nx monorepo y c\xf3mo mejora la arquitectura de un proyecto React? Nx (de Nrwl) ofrece generators, dependency graph, affected commands, y computation caching."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Nx es un build system para monorepos que ofrece: (1) generators para crear features/componentes con estructura consistente, (2) dependency graph autom\xe1tico (detecta dependencias circulares, muestra el grafo visual), (3) affected commands: ",(0,s.jsx)(a.code,{children:"nx affected:test"})," solo ejecuta tests de proyectos afectados por un cambio, (4) computation caching: builds/tests cacheados. En un monorepo manual (TaskFlow), tendr\xedas que implementar esto manualmente o no tenerlo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Nx brilla en monorepos con m\xfaltiples aplicaciones y librer\xedas compartidas. Para TaskFlow (una sola app React), Nx es overkill. Pero para un proyecto con React frontend + React Native mobile + librer\xeda de componentes compartida, Nx es invaluable. Fuente: nx.dev, "Why Nx for React" en el blog de Nrwl, y la comparaci\xf3n Nx vs Turborepo vs Lerna.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-bulletproof-react-de-alan-alickovic-y-c\xf3mo-estructura-un-proyecto-react-production-ready-compar\xe1-su-enfoque-con-la-arquitectura-de-la-clase",children:'3. [Investigar] \xbfQu\xe9 es "Bulletproof React" (de Alan Alickovic) y c\xf3mo estructura un proyecto React "production-ready"? Compar\xe1 su enfoque con la arquitectura de la clase.'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Bulletproof React propone: (1) ",(0,s.jsx)(a.code,{children:"src/features/"})," con cada feature autocontenida (similar a la clase), (2) separaci\xf3n estricta de API layer (funciones puras, no hooks), (3) componentes divididos en Elements/Form/Layout, (4) store por feature con Zustand, (5) testing colocado junto al c\xf3digo. Comparado con la clase: Bulletproof React va m\xe1s all\xe1 en separaci\xf3n de capas (API layer separada de hooks) y en convenciones estrictas de testing con tests al lado del archivo fuente."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Alan Alickovic document\xf3 patrones de arquitectura React observados en proyectos enterprise exitosos. La recomendaci\xf3n de Bulletproof React de mantener la API layer pura (",(0,s.jsx)(a.code,{children:"export const getTasks = () => axios.get(...)"}),") y que los hooks la consuman hace el c\xf3digo m\xe1s testeable (la API layer se testea con mocks de axios, los hooks con ",(0,s.jsx)(a.code,{children:"renderHook"}),'). Fuente: github.com/alan2207/bulletproof-react, "Bulletproof React Architecture" en el blog de Alan Alickovic.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-tao-of-react-de-alexander-kondov-y-qu\xe9-principios-de-arquitectura-propone-que-difieren-de-la-clase",children:'4. [Investigar] \xbfQu\xe9 es "Tao of React" (de Alexander Kondov) y qu\xe9 principios de arquitectura propone que difieren de la clase?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': "Tao of React" propone minimalismo: (1) no crear carpetas hasta que sean necesarias (empezar con todo en un archivo), (2) colocar archivos seg\xfan dependencias, no seg\xfan tipo (un hook que solo usa un componente va en la carpeta de ese componente), (3) evitar abstracciones prematuras, (4) componentes "stupid" (solo renderizar), l\xf3gica en hooks. Difiere de la arquitectura de la clase porque es m\xe1s pragm\xe1tico y menos dogm\xe1tico sobre la estructura de carpetas inicial.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Alexander Kondov critica la sobre-estructuraci\xf3n inicial y propone una arquitectura org\xe1nica que evoluciona con el proyecto. Para TaskFlow, la arquitectura de la clase es un balance: suficiente estructura para ser mantenible, sin sobre-ingenier\xeda. Fuente: alexkondov.com/tao-of-react, "The Tao of React" por Alexander Kondov.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-presenta-clean-architecture-y-atomic-design-conect\xe1-estos-conceptos-con-el-libro-clean-architecture-de-robert-c-martin-c\xf3mo-se-traducen-dependency-rule-entities-y-use-cases-al-frontend-react",children:'5. [Conectar] La clase presenta Clean Architecture y Atomic Design. Conect\xe1 estos conceptos con el libro "Clean Architecture" de Robert C. Martin. \xbfC\xf3mo se traducen "dependency rule", "entities", y "use cases" al frontend React?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Clean Architecture en frontend: Entities = tipos TypeScript puros (",(0,s.jsx)(a.code,{children:"Task"}),", ",(0,s.jsx)(a.code,{children:"User"})," sin dependencias de React). Use Cases = custom hooks (",(0,s.jsx)(a.code,{children:"useCreateTask"}),") y stores de Zustand. Interface Adapters = API layer, localStorage wrapper. Frameworks & Drivers = componentes React, React Router. La Dependency Rule: las capas externas dependen de internas (componentes dependen de hooks, hooks dependen de tipos, nunca al rev\xe9s). Atomic Design complementa esto organizando la UI en Atoms \u2192 Molecules \u2192 Organisms \u2192 Templates \u2192 Pages."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La adaptaci\xf3n de Clean Architecture al frontend no es 1:1 porque React est\xe1 en todas partes. Pero el principio de que la l\xf3gica de negocio no debe depender de React es valioso: un store de Zustand es independiente de React y testeable sin montar componentes. Fuente: "Clean Architecture" por Robert C. Martin, "Clean Architecture in React" en m\xfaltiples blogs.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"6-conectar-la-clase-organiza-features-con-carpetas-autocontenidas-conect\xe1-esto-con-cohesi\xf3n-funcional-vs-cohesi\xf3n-t\xe9cnica-por-qu\xe9-agrupar-por-feature-es-superior-a-agrupar-por-tipo-en-proyectos-grandes",children:'6. [Conectar] La clase organiza features con carpetas autocontenidas. Conect\xe1 esto con "cohesi\xf3n funcional" vs "cohesi\xf3n t\xe9cnica". \xbfPor qu\xe9 agrupar por feature es superior a agrupar por tipo en proyectos grandes?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Cohesi\xf3n funcional (feature-based) agrupa c\xf3digo que cambia junto: modificar auth toca solo ",(0,s.jsx)(a.code,{children:"features/auth/"}),". Cohesi\xf3n t\xe9cnica (layer-based) dispersa el cambio en m\xfaltiples carpetas (",(0,s.jsx)(a.code,{children:"components/"}),", ",(0,s.jsx)(a.code,{children:"hooks/"}),", ",(0,s.jsx)(a.code,{children:"store/"}),", ",(0,s.jsx)(a.code,{children:"services/"}),"). En proyectos grandes, la cohesi\xf3n funcional reduce la carga cognitiva, facilita code-splitting (cada feature puede ser un chunk), y permite que equipos trabajen en features independientes sin conflictos de merge. La cohesi\xf3n t\xe9cnica es m\xe1s simple inicialmente pero no escala."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La ley de Conway aplica: la estructura del c\xf3digo refleja la estructura de comunicaci\xf3n del equipo. Si ten\xe9s equipos por feature (equipo auth, equipo tasks), la arquitectura feature-based minimiza la coordinaci\xf3n entre equipos. Fuente: "Cohesion and Coupling in Software Design" por John Ousterhout, discusiones en el blog de Kent C. Dodds sobre estructura de carpetas.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"7-conectar-la-clase-usa-eslint-strict-rules-conect\xe1-esto-con-el-concepto-de-static-analysis-beyond-eslint-qu\xe9-herramientas-complementan-eslint-para-mantener-la-calidad-de-c\xf3digo-en-un-proyecto-react",children:'7. [Conectar] La clase usa ESLint strict rules. Conect\xe1 esto con el concepto de "static analysis beyond ESLint". \xbfQu\xe9 herramientas complementan ESLint para mantener la calidad de c\xf3digo en un proyecto React?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": M\xe1s all\xe1 de ESLint: (1) TypeScript strict mode + ",(0,s.jsx)(a.code,{children:"noUncheckedIndexedAccess"})," + ",(0,s.jsx)(a.code,{children:"exactOptionalPropertyTypes"})," (prevenci\xf3n de bugs de tipos), (2) Prettier (formateo consistente, reduce discusiones en PRs), (3) Knip (detecta imports, exports, y dependencias no usados), (4) depcheck (detecta dependencias npm no usadas), (5) bundle size checker (previene que PRs incrementen el bundle sin intenci\xf3n), (6) typesync (sincroniza @types con dependencias), (7) sherif (valida consistencia de package.json en monorepos). Juntas, estas herramientas automatizan la higiene del c\xf3digo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': ESLint detecta problemas de estilo y l\xf3gica, pero no detecta imports muertos (Knip), dependencias no usadas (depcheck), o tipos flojos (TypeScript strict). La combinaci\xf3n de herramientas de static analysis crea una "red de seguridad" que previene que c\xf3digo de baja calidad llegue a producci\xf3n. Fuente: github.com/webpro-nl/knip, depcheck docs, y "Beyond ESLint: Static Analysis for JS" en el blog de Anton Medvedev.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-feature-based-vs-domain-driven-design-ddd-en-frontend-la-clase-usa-feature-based-deber\xedamos-aplicar-conceptos-de-ddd-aggregates-bounded-contexts-a-la-arquitectura-react",children:"8. [Cuestionar] \xbfFeature-based vs Domain-Driven Design (DDD) en frontend? La clase usa feature-based. \xbfDeber\xedamos aplicar conceptos de DDD (aggregates, bounded contexts) a la arquitectura React?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Feature-based es el equivalente pr\xe1ctico de DDD Bounded Contexts en frontend: cada feature es un bounded context con su propio lenguaje ubicuo, entidades, y reglas. DDD completo (aggregates, value objects, domain events, repositories) suele ser overkill para frontend, pero los principios aplican: (1) bounded context = feature folder, (2) aggregate = store de Zustand, (3) domain event = acciones del store, (4) repository = API layer. Para TaskFlow, feature-based es suficiente. DDD completo tendr\xeda sentido en una app con l\xf3gica de negocio muy compleja (seguros, fintech) donde las reglas de negocio dominan."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': El frontend es principalmente presentaci\xf3n y orquestaci\xf3n. La l\xf3gica de negocio compleja deber\xeda vivir en el backend. El frontend refleja los bounded contexts del backend, pero no necesita modelar aggregates completos. Fuente: "Domain-Driven Design in Frontend" por Khalil Stemmler, "DDD for React Apps" en el blog de Stately, y discusiones en la comunidad de Arquitectura de Software.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"9-cuestionar-monorepo-vs-polyrepo-para-proyectos-react-la-clase-usa-un-solo-repo-cu\xe1ndo-un-polyrepo-m\xfaltiples-repos-es-mejor",children:"9. [Cuestionar] \xbfMonorepo vs polyrepo para proyectos React? La clase usa un solo repo. \xbfCu\xe1ndo un polyrepo (m\xfaltiples repos) es mejor?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Monorepo: mejor para proyectos donde el frontend y backend (o m\xfaltiples frontends) comparten c\xf3digo (tipos, utilidades, configuraciones) y se despliegan juntos. Polyrepo: mejor para equipos completamente independientes con ciclos de release diferentes, o cuando el frontend y backend son mantenidos por organizaciones separadas. Para TaskFlow (frontend + Spring Boot), un monorepo (o repo separado por stack) es apropiado. Polyrepo ser\xeda \xfatil si el equipo de frontend y backend tienen ciclos de sprint independientes y nunca comparten c\xf3digo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': El debate monorepo vs polyrepo es resuelto por herramientas modernas: Turborepo/Nx para monorepos con m\xfaltiples apps, o GitHub Actions separados para polyrepos. La tendencia es hacia monorepos por la simplicidad de compartir tipos y configuraciones. Google, Meta, y Microsoft usan monorepos masivos. Fuente: "Monorepo vs Multirepo" en el blog de Semaphore, "Why Google uses a monorepo" en ACM, y la experiencia de Vercel con Turborepo.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-atomic-design-es-sobre-ingenier\xeda-para-la-mayor\xeda-de-proyectos-react-brad-frost-cre\xf3-atomic-design-para-design-systems-cu\xe1ndo-justifica-su-uso-y-cu\xe1ndo-es-una-estructura-innecesaria",children:"10. [Cuestionar] \xbfAtomic Design es sobre-ingenier\xeda para la mayor\xeda de proyectos React? Brad Frost cre\xf3 Atomic Design para design systems. \xbfCu\xe1ndo justifica su uso y cu\xe1ndo es una estructura innecesaria?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Atomic Design es valioso cuando constru\xeds un design system reutilizable (librer\xeda de componentes para m\xfaltiples aplicaciones). Para una sola aplicaci\xf3n (TaskFlow), la distinci\xf3n estricta entre atoms y molecules puede ser innecesaria \u2014 los componentes pueden organizarse simplemente en ",(0,s.jsx)(a.code,{children:"components/ui/"})," (gen\xe9ricos) y ",(0,s.jsx)(a.code,{children:"features/*/components/"})," (espec\xedficos). La sobre-ingenier\xeda ocurre cuando gast\xe1s m\xe1s tiempo clasificando componentes (\xbfesto es atom o molecule?) que construyendo la aplicaci\xf3n. La recomendaci\xf3n: aplic\xe1 los principios de Atomic Design (composici\xf3n, reusabilidad) sin el rigor taxon\xf3mico."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Brad Frost mismo ha dicho que Atomic Design es una "met\xe1fora" y una "herramienta de pensamiento", no una especificaci\xf3n r\xedgida. En proyectos reales, la l\xednea entre atom y molecule es difusa. Enfocate en el principio (componentes peque\xf1os que se componen) en lugar de la taxonom\xeda exacta. Fuente: "Atomic Design" por Brad Frost, "Atomic Design in Practice" en el blog de Brad Frost, y discusiones en la comunidad sobre la aplicaci\xf3n pragm\xe1tica del patr\xf3n.']})]})}function l(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,a,o){o.d(a,{R:()=>t,x:()=>c});var n=o(96540);const s={},r=n.createContext(s);function t(e){const a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:t(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);